CREATE OR REPLACE FUNCTION public.sync_program_days(p_program_id uuid, p_days jsonb) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid uuid := auth.uid(); v_day jsonb; v_ex jsonb; v_weekday int; v_name text; v_day_id uuid; v_used uuid[] := '{}'; v_order int := 0; v_ex_count int; v_day_total int := 0; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF p_program_id IS NULL OR p_days IS NULL OR jsonb_typeof(p_days) <> 'array' THEN RAISE EXCEPTION 'Invalid payload'; END IF; IF jsonb_array_length(p_days) > 14 THEN RAISE EXCEPTION 'Too many days'; END IF; IF NOT EXISTS (SELECT 1 FROM public.programs p WHERE p.id = p_program_id AND p.owner_id = v_uid) THEN RAISE EXCEPTION 'Not program owner'; END IF; FOR v_day IN SELECT * FROM jsonb_array_elements(p_days) LOOP BEGIN v_weekday := (v_day->>'weekday')::int; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'Invalid weekday'; END; IF v_weekday IS NULL OR v_weekday < 0 OR v_weekday > 6 THEN RAISE EXCEPTION 'Invalid weekday'; END IF; IF v_day->'exercises' IS NULL OR jsonb_typeof(v_day->'exercises') <> 'array' THEN RAISE EXCEPTION 'Invalid exercises for day %', v_weekday; END IF; IF jsonb_array_length(v_day->'exercises') > 100 THEN RAISE EXCEPTION 'Too many exercises'; END IF; FOR v_ex IN SELECT * FROM jsonb_array_elements(v_day->'exercises') LOOP v_name := NULLIF(btrim(COALESCE(v_ex->>'name', '')), ''); IF v_name IS NULL THEN RAISE EXCEPTION 'Exercise name required'; END IF; END LOOP; END LOOP; FOR v_day IN SELECT * FROM jsonb_array_elements(p_days) LOOP v_weekday := (v_day->>'weekday')::int; SELECT d.id INTO v_day_id FROM public.program_days d WHERE d.program_id = p_program_id AND d.weekday = v_weekday AND NOT (d.id = ANY (v_used)) LIMIT 1; IF v_day_id IS NULL THEN INSERT INTO public.program_days (program_id, weekday, name, routine_id, order_index) VALUES (p_program_id, v_weekday, COALESCE(v_day->>'name', ''), NULL, v_order) RETURNING id INTO v_day_id; ELSE UPDATE public.program_days SET name = COALESCE(v_day->>'name', name), weekday = v_weekday, order_index = v_order WHERE id = v_day_id; END IF; v_used := v_used || v_day_id; v_order := v_order + 1; DELETE FROM public.program_day_exercises WHERE program_day_id = v_day_id; v_ex_count := 0; FOR v_ex IN SELECT * FROM jsonb_array_elements(v_day->'exercises') LOOP INSERT INTO public.program_day_exercises (program_day_id, name, default_sets, default_reps, default_reps_min, default_rir, default_rest_seconds, default_weight_kg, order_index) VALUES (v_day_id, btrim(v_ex->>'name'), COALESCE((v_ex->>'default_sets')::int, 3), COALESCE((v_ex->>'default_reps')::int, 10), NULLIF(v_ex->>'default_reps_min', '')::int, NULLIF(v_ex->>'default_rir', '')::int, COALESCE((v_ex->>'default_rest_seconds')::int, 90), NULLIF(v_ex->>'default_weight_kg', '')::numeric, COALESCE((v_ex->>'order_index')::int, v_ex_count)); v_ex_count := v_ex_count + 1; END LOOP; v_day_total := v_day_total + 1; END LOOP; DELETE FROM public.program_days d WHERE d.program_id = p_program_id AND NOT (d.id = ANY (v_used)); UPDATE public.programs SET updated_at = now() WHERE id = p_program_id; RETURN v_day_total; END; $$;
